 static string Clean(string s){return (s??"").Replace("\r","").Replace("\n","");}static string CH(Color c){return c.ToArgb().ToString("X8");}static Color PC(string s,Color fallback){int n;if(int.TryParse(s,System.Globalization.NumberStyles.HexNumber,System.Globalization.CultureInfo.InvariantCulture,out n))return Color.FromArgb(n);return fallback;} void LoadConfig(){float f;int v;try{if(File.Exists(configPath))foreach(string raw in File.ReadAllLines(configPath)){string s=raw.Trim();if(s.Length==0||s.StartsWith("#")||s.StartsWith(";")||s.StartsWith("["))continue;int q=s.IndexOf("="[0]);if(q<1)continue;string k=s.Substring(0,q).Trim().ToLowerInvariant(),z=s.Substring(q+1).Trim();if(k=="theme")themeId=EffectThemes.Find(z).Id;else if(k=="cursorshape")cursorShapeId=CursorShapes.Find(z).Id;else if(k=="customthemename")EffectThemes.Custom.Name=z;else if(k=="customshadow")EffectThemes.Custom.Shadow=PC(z,EffectThemes.Custom.Shadow);else if(k=="customprimary")EffectThemes.Custom.Primary=PC(z,EffectThemes.Custom.Primary);else if(k=="customsecondary")EffectThemes.Custom.Secondary=PC(z,EffectThemes.Custom.Secondary);else if(k=="customglow")EffectThemes.Custom.Glow=PC(z,EffectThemes.Custom.Glow);else if(k=="customcore")EffectThemes.Custom.Core=PC(z,EffectThemes.Custom.Core);else if(k=="trailwidth"&&float.TryParse(z,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out f))trailScale=Math.Max(.5f,Math.Min(1.5f,f));else if(k=="traillifems"&&int.TryParse(z,out v))trailLife=Math.Max(220,Math.Min(900,v));else if(k=="effectscale"&&float.TryParse(z,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out f))effectScale=Math.Max(.65f,Math.Min(1.5f,f));else if(k=="particlescale"&&float.TryParse(z,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out f))particleScale=Math.Max(0,Math.Min(1.6f,f));else if(k=="cursoreffect")cursorFxEnabled=z!="0"&&!z.Equals("false",StringComparison.OrdinalIgnoreCase);else if(k=="frameintervalms"&&int.TryParse(z,out v))frameMs=Math.Max(20,Math.Min(60,v));else if(k=="maxtrailpoints"&&int.TryParse(z,out v))maxTrail=Math.Max(50,Math.Min(180,v));else if(k=="maxsamples"&&int.TryParse(z,out v))maxSamples=Math.Max(3,Math.Min(10,v));}}catch{}cursorShapeId=CursorShapes.Find(cursorShapeId).Id;timer.Interval=frameMs;}
