 void Toggle(){enabled=!enabled;if(!enabled)lock(gate){trail.Clear();dust.Clear();clicks.Clear();}SyncCursorForRunState();if(tray!=null)tray.Text=enabled?"magic&miracle · 运行中":"magic&miracle · 已暂停";if(panel!=null&&!panel.IsDisposed){panel.Text=enabled?"magic&miracle":"magic&miracle · 已暂停";panel.SyncFromHost();}Render();}
 static bool CursorVisible(){var c=new N.CI{Size=Marshal.SizeOf(typeof(N.CI))};return !N.GetCursorInfo(ref c)||(c.Flags&N.SHOWING)!=0;}
 IntPtr Hook(int code,IntPtr w,IntPtr l){int msg=w.ToInt32();if(code>=0&&enabled){if(!CursorVisible()){leftHeld=false;dragging=false;return N.CallNextHookEx(hook,code,w,l);}var d=(N.M)Marshal.PtrToStructure(l,typeof(N.M));float x=d.Pt.X-Left,y=d.Pt.Y-Top;DateTime now=DateTime.UtcNow;if(msg==N.LD){bool dbl=(now-lastClickAt).TotalMilliseconds<320&&Math.Abs(x-lastClickPoint.X)<18&&Math.Abs(y-lastClickPoint.Y)<18;leftHeld=true;dragging=false;pressPoint=new Point((int)x,(int)y);pressAt=now;lastClickAt=now;lastClickPoint=pressPoint;Emit(x,y,dbl?4:7);}else if(msg==N.LU){if(leftHeld)Emit(x,y,dragging?6:0);leftHeld=false;dragging=false;}else if(msg==N.RD)Emit(x,y,1);else if(msg==N.MD)Emit(x,y,5);else if(msg==N.WHEEL){short delta=(short)(d.Data>>16);Emit(x,y,delta>0?2:3);}else if(msg==N.XDOWN)Emit(x,y,((d.Data>>16)&0xffff)==1?8:9);}return N.CallNextHookEx(hook,code,w,l);}
