 static Color HSV(double h,double s,double v,int a){h=(h%360+360)%360;int z=(int)Math.Floor(h/60)%6;double f=h/60-Math.Floor(h/60);v*=255;int vv=(int)v,p=(int)(v*(1-s)),q=(int)(v*(1-f*s)),t=(int)(v*(1-(1-f)*s));switch(z){case 0:return Color.FromArgb(a,vv,t,p);case 1:return Color.FromArgb(a,q,vv,p);case 2:return Color.FromArgb(a,p,vv,t);case 3:return Color.FromArgb(a,p,q,vv);case 4:return Color.FromArgb(a,t,p,vv);default:return Color.FromArgb(a,vv,p,q);}}
