 protected override void OnFormClosed(FormClosedEventArgs e){timer.Stop();N.SystemParametersInfo(N.SPI_SETCURSORS,0,IntPtr.Zero,0);if(showRegistration!=null)showRegistration.Unregister(null);if(hotKeyRegistered)N.UnregisterHotKey(Handle,N.HID);if(keyHook!=IntPtr.Zero)N.UnhookWindowsHookEx(keyHook);if(hook!=IntPtr.Zero)N.UnhookWindowsHookEx(hook);if(panel!=null&&!panel.IsDisposed)panel.ForceClose();if(tray!=null){tray.Visible=false;tray.Dispose();}if(trayIcon!=null)trayIcon.Dispose();if(canvas!=null)canvas.Dispose();try{if(!string.IsNullOrEmpty(cursorTempPath)&&File.Exists(cursorTempPath))File.Delete(cursorTempPath);if(!string.IsNullOrEmpty(handTempPath)&&File.Exists(handTempPath))File.Delete(handTempPath);if(!string.IsNullOrEmpty(workingTempPath)&&File.Exists(workingTempPath))File.Delete(workingTempPath);if(!string.IsNullOrEmpty(waitTempPath)&&File.Exists(waitTempPath))File.Delete(waitTempPath);}catch{}base.OnFormClosed(e);}
