static class Program {static Mutex single;[STAThread]static void Main(string[] args){bool first;single=new Mutex(true,"CosmicChromeMouse.SingleInstance",out first);if(!first){try{using(var wake=EventWaitHandle.OpenExisting("CosmicChromeMouse.ShowSettings"))wake.Set();}catch{}return;}bool show=true;foreach(string a in args)if(string.Equals(a,"--minimized",StringComparison.OrdinalIgnoreCase))show=false;try{N.SetProcessDpiAwarenessContext(new IntPtr(-4));}catch{}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var signal=new EventWaitHandle(false,EventResetMode.AutoReset,"CosmicChromeMouse.ShowSettings"))Application.Run(new FX(show,signal));GC.KeepAlive(single);}}
